-- user creates topics and uploads documents into it
CREATE TABLE topics (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    name TEXT NOT NULL,
    created_by UUID,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- documents belong to a topic
ALTER TABLE documents
    ADD COLUMN topic_id UUID NOT NULL REFERENCES topics(id) ON DELETE CASCADE;

CREATE INDEX documents_topic_id_idx ON documents (topic_id);

-- store the questions generated by the clanker
-- keep a reference to the document used, maybe not required?
CREATE TABLE tasks (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    document_id UUID NOT NULL REFERENCES documents(id) ON DELETE RESTRICT,
    question_type TEXT NOT NULL,
    content JSONB NOT NULL DEFAULT '{}'::jsonb
        CHECK (jsonb_typeof(content) = 'object'),
    solution JSONB NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE instructions (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    instruction JSONB NOT NULL DEFAULT '{}'::jsonb,
    task_id UUID NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    UNIQUE (id, task_id)
);

CREATE INDEX tasks_document_id_idx ON tasks (document_id);
CREATE INDEX instructions_task_id_idx ON instructions (task_id);

-- game consists of a backing topic for questions, the defuser, the exper with the manual and game events
CREATE TABLE games (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    topic_id UUID NOT NULL REFERENCES topics(id) ON DELETE RESTRICT,
    defuser_id UUID NOT NULL,
    expert_id UUID NOT NULL,
    status TEXT NOT NULL DEFAULT 'active'
        CHECK (status IN ('active', 'won', 'lost', 'waiting')),
    failure_count SMALLINT NOT NULL DEFAULT 0
        CHECK (failure_count BETWEEN 0 AND 3),
    next_event_sequence INTEGER NOT NULL DEFAULT 0
        CHECK (next_event_sequence >= 0),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    ended_at TIMESTAMPTZ,
    CHECK (defuser_id <> expert_id),
    CHECK (
        (status = 'active' AND ended_at IS NULL)
        OR (status IN ('won', 'lost') AND ended_at IS NOT NULL)
    )
);

CREATE INDEX games_topic_id_idx ON games (topic_id);
CREATE INDEX games_defuser_id_idx ON games (defuser_id);
CREATE INDEX games_expert_id_idx ON games (expert_id);

CREATE TABLE game_parts (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    game_id UUID NOT NULL REFERENCES games(id) ON DELETE CASCADE,
    task_id UUID NOT NULL REFERENCES tasks(id) ON DELETE RESTRICT,
    instruction_id UUID NOT NULL,
    position INTEGER NOT NULL CHECK (position >= 0),
    solved_at TIMESTAMPTZ,
    UNIQUE (game_id, position),
    UNIQUE (game_id, task_id),
    FOREIGN KEY (instruction_id, task_id)
        REFERENCES instructions(id, task_id) ON DELETE RESTRICT
);

CREATE INDEX game_parts_game_id_idx ON game_parts (game_id);

CREATE TABLE game_events (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    game_id UUID NOT NULL REFERENCES games(id) ON DELETE CASCADE,
    sequence INTEGER NOT NULL CHECK (sequence >= 0),
    actor_id UUID,
    event_type TEXT NOT NULL
        CHECK (event_type IN ('answer_submitted', 'game_ended')),
    payload JSONB NOT NULL DEFAULT '{}'::jsonb
        CHECK (jsonb_typeof(payload) = 'object'),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (game_id, sequence)
);

CREATE UNIQUE INDEX game_events_one_end_per_game_idx
    ON game_events (game_id)
    WHERE event_type = 'game_ended';
